var server,helpers=require("./helpers"),should=require("should"),needle=require("./../"),port=7707;describe("Basic Auth",function(){before(function(e){server=helpers.server({port:port},e)}),after(function(e){server.close(e)});var e=function(e){var o=e.split(/\s+/).pop();return o&&Buffer.from(o,"base64").toString().split(":")};describe("when neither username or password are passed",function(){it("doesnt send any Authorization headers",function(e){needle.get("localhost:"+port,{parse:!0},function(o,n){var a=n.body.headers;Object.keys(a).should.not.containEql("authorization"),e()})})}),describe("when username is an empty string, and password is a valid string",function(){it("doesnt send any Authorization headers",function(e){needle.get("localhost:"+port,{parse:!0},function(o,n){var a=n.body.headers;Object.keys(a).should.not.containEql("authorization"),e()})})}),describe("when username is a valid string, but no username is passed",function(){var o={username:"foobar",parse:!0};it("sends Authorization header",function(e){needle.get("localhost:"+port,o,function(o,n){var a=n.body.headers;Object.keys(a).should.containEql("authorization"),e()})}),it("Basic Auth only includes username, without colon",function(n){needle.get("localhost:"+port,o,function(o,a){var t=a.body.headers,s=e(t.authorization);s[0].should.equal("foobar"),s.should.have.lengthOf(1),n()})})}),describe("when username is a valid string, and password is null",function(){var o={username:"foobar",password:null,parse:!0};it("sends Authorization header",function(e){needle.get("localhost:"+port,o,function(o,n){var a=n.body.headers;Object.keys(a).should.containEql("authorization"),e()})}),it("Basic Auth only includes both username and password",function(n){needle.get("localhost:"+port,o,function(o,a){var t=a.body.headers,s=e(t.authorization);s[0].should.equal("foobar"),s[1].should.equal(""),n()})})}),describe("when username is a valid string, and password is an empty string",function(){var o={username:"foobar",password:"",parse:!0};it("sends Authorization header",function(e){needle.get("localhost:"+port,o,function(o,n){var a=n.body.headers;Object.keys(a).should.containEql("authorization"),e()})}),it("Basic Auth only includes both username and password",function(n){needle.get("localhost:"+port,o,function(o,a){var t=a.body.headers,s=e(t.authorization);s[0].should.equal("foobar"),s[1].should.equal(""),s.should.have.lengthOf(2),n()})})}),describe("when username AND password are non empty strings",function(){var o={username:"foobar",password:"jakub",parse:!0};it("sends Authorization header",function(e){needle.get("localhost:"+port,o,function(o,n){var a=n.body.headers;Object.keys(a).should.containEql("authorization"),e()})}),it("Basic Auth only includes both user and password",function(n){needle.get("localhost:"+port,o,function(o,a){var t=a.body.headers,s=e(t.authorization);s[0].should.equal("foobar"),s[1].should.equal("jakub"),s.should.have.lengthOf(2),n()})})}),describe("URL with @ but not username/pass",function(){it("doesnt send Authorization header",function(e){var o="localhost:"+port+"/abc/@def/xyz.zip";needle.get(o,{},function(o,n){var a=n.body.headers;Object.keys(a).should.not.containEql("authorization"),e()})}),it("sends user:pass headers if passed via options",function(e){var o="localhost:"+port+"/abc/@def/xyz.zip";needle.get(o,{username:"foo"},function(o,n){var a=n.body.headers;Object.keys(a).should.containEql("authorization"),a.authorization.should.eql("Basic Zm9v"),e()})})}),describe("when username/password are included in URL",function(){var o={parse:!0};it("sends Authorization header",function(e){needle.get("foobar:jakub@localhost:"+port,o,function(o,n){var a=n.body.headers;Object.keys(a).should.containEql("authorization"),e()})}),it("Basic Auth only includes both user and password",function(n){needle.get("foobar:jakub@localhost:"+port,o,function(o,a){var t=a.body.headers,s=e(t.authorization);s[0].should.equal("foobar"),s[1].should.equal("jakub"),s.should.have.lengthOf(2),n()})})})});